  "data": {
    "command": "astryx experimental render",
    "description": "[experimental] Render a page to one self-contained HTML file, or turn one back into a page",
    "usage": "astryx experimental render [options] [file]",
    "options": [
      {
        "flags": "--out <file>",
        "description": "Where to write: an .html file, or with --reverse a page module (default: page.tsx gives page.html beside it; with --reverse, page.html comes back into a new folder page-restored/)"
      },
      {
        "flags": "--reverse",
        "description": "Turn a rendered HTML file back into a page module"
      },
      {
        "flags": "--title <text>",
        "description": "The page's title (default: its first top-level heading, else the file name)"
      },
      {
        "flags": "--overwrite",
        "description": "With --reverse, replace the page module if it already exists (never a protected file; the files it imports always go into a new folder)"
      }
    ],
    "subcommands": []
  },
